python3 - <<'EOF'
import re

batch_path = "/tmp/opencode/compat_batch2.tsv"
rows = []
with open(batch_path) as f:
    for line in f:
        line = line.rstrip("\n")
        if not line.strip():
            continue
        parts = line.split("\t")
        rows.append((parts[0], parts[1], parts[2]))

def derive_fn(msg, id_):
    if id_ == "AXSTATE":
        return "axis"
    if msg.startswith("The '") and " of '" in msg:
        m = re.search(r"of '([^']+)'", msg)
        return m.group(1)
    quoted = re.findall(r"'([^']+)'", msg)
    if not quoted:
        return ""
    first = quoted[0]
    if first.endswith(")"):
        return first.split("(")[0]
    return first

# show any messages with double quotes or backslashes
for id_, sev, msg in rows:
    if '"' in msg or '\\' in msg:
        print(repr(msg))
print("---derived I2CFUN:", derive_fn(rows[197][2], rows[197][0]))
# verify all "The '" starts
for id_, sev, msg in rows:
    if msg.startswith("The '"):
        print(id_, derive_fn(msg, id_))
EOF

